using ArchUnitNET.Domain;
using ArchUnitNET.Fluent;
using ArchUnitNET.Loader;
using ArchUnitNET.xUnit;
using Xunit;
using RefAssembly = System.Reflection.Assembly;
using static ArchUnitNET.Fluent.ArchRuleDefinition;

namespace WriteLike.ArchitectureTests;

/// <summary>
/// The dependency matrix of WriteLike, expressed as executable tests.
/// If one of these fails, the CODE is in the wrong place — do not edit this file.
/// </summary>
public sealed class LayerBoundaryTests
{
    private static readonly RefAssembly Domain =
        typeof(WriteLike.Domain.AssemblyReference).Assembly;
    private static readonly RefAssembly Application =
        typeof(WriteLike.Application.AssemblyReference).Assembly;
    private static readonly RefAssembly Ai =
        typeof(WriteLike.Ai.AssemblyReference).Assembly;
    private static readonly RefAssembly Infrastructure =
        typeof(WriteLike.Infrastructure.AssemblyReference).Assembly;
    private static readonly RefAssembly Composition =
        typeof(WriteLike.Composition.AssemblyReference).Assembly;
    private static readonly RefAssembly Api =
        typeof(WriteLike.Api.AssemblyReference).Assembly;

    private static readonly Architecture Architecture = new ArchLoader()
        .LoadAssemblies(Domain, Application, Ai, Infrastructure, Composition, Api)
        .Build();

    private static readonly IObjectProvider<IType> DomainLayer =
        Types().That().ResideInAssembly(Domain).As("Domain");

    private static readonly IObjectProvider<IType> ApplicationLayer =
        Types().That().ResideInAssembly(Application).As("Application");

    private static readonly IObjectProvider<IType> AiLayer =
        Types().That().ResideInAssembly(Ai).As("Ai");

    private static readonly IObjectProvider<IType> InfrastructureLayer =
        Types().That().ResideInAssembly(Infrastructure).As("Infrastructure");

    private static readonly IObjectProvider<IType> CompositionLayer =
        Types().That().ResideInAssembly(Composition).As("Composition");

    private static readonly IObjectProvider<IType> ApiLayer =
        Types().That().ResideInAssembly(Api).As("Api");

    [Fact]
    public void DomainMustNotDependOnAnythingOutward()
        => Types().That().Are(DomainLayer).Should().NotDependOnAny(ApplicationLayer).Because(Innermost)
            .And(Types().That().Are(DomainLayer).Should().NotDependOnAny(AiLayer).Because(Innermost))
            .And(Types().That().Are(DomainLayer).Should().NotDependOnAny(InfrastructureLayer).Because(Innermost))
            .And(Types().That().Are(DomainLayer).Should().NotDependOnAny(CompositionLayer).Because(Innermost))
            .And(Types().That().Are(DomainLayer).Should().NotDependOnAny(ApiLayer).Because(Innermost))
            .Check(Architecture);

    [Fact]
    public void ApplicationMustOnlyDependOnDomain()
        => Types().That().Are(ApplicationLayer).Should().NotDependOnAny(AiLayer).Because(PortsRule)
            .And(Types().That().Are(ApplicationLayer).Should().NotDependOnAny(InfrastructureLayer).Because(PortsRule))
            .And(Types().That().Are(ApplicationLayer).Should().NotDependOnAny(CompositionLayer).Because(PortsRule))
            .And(Types().That().Are(ApplicationLayer).Should().NotDependOnAny(ApiLayer).Because(PortsRule))
            .Check(Architecture);

    [Fact]
    public void AiMustOnlyDependOnDomainAndApplication()
        => Types().That().Are(AiLayer).Should().NotDependOnAny(InfrastructureLayer).Because(AiRule)
            .And(Types().That().Are(AiLayer).Should().NotDependOnAny(CompositionLayer).Because(AiRule))
            .And(Types().That().Are(AiLayer).Should().NotDependOnAny(ApiLayer).Because(AiRule))
            .Check(Architecture);

    [Fact]
    public void InfrastructureMustOnlyDependOnDomainAndApplication()
        => Types().That().Are(InfrastructureLayer).Should().NotDependOnAny(AiLayer).Because(InfrastructureRule)
            .And(Types().That().Are(InfrastructureLayer).Should().NotDependOnAny(CompositionLayer).Because(InfrastructureRule))
            .And(Types().That().Are(InfrastructureLayer).Should().NotDependOnAny(ApiLayer).Because(InfrastructureRule))
            .Check(Architecture);

    [Fact]
    public void ApiMustOnlySeeApplicationAndComposition()
        => Types().That().Are(ApiLayer).Should().NotDependOnAny(DomainLayer).Because(ApiRule)
            .And(Types().That().Are(ApiLayer).Should().NotDependOnAny(AiLayer).Because(ApiRule))
            .And(Types().That().Are(ApiLayer).Should().NotDependOnAny(InfrastructureLayer).Because(ApiRule))
            .Check(Architecture);

    private const string Innermost =
        "Domain is the innermost layer — it is pure business with zero outward knowledge";

    private const string PortsRule =
        "Application defines use cases and ports; implementations live in Infrastructure/Ai";

    private const string AiRule =
        "The OpenCode pipeline persists via Application ports, never directly";

    private const string InfrastructureRule =
        "Infrastructure implements ports; it knows nothing of the pipeline or the host";

    private const string ApiRule =
        "Api goes through Application use cases/ports; Infrastructure is wired by Composition only";
}
